  static class EngineBridge {
    public static int RetentionLimit=1500;
    public static bool FixedMode=false;
    public static double FixedValue=8.8;
    public static int ReadCoreFragments(string json){try{var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};var root=js.DeserializeObject(File.ReadAllText(json,Encoding.UTF8)) as Dictionary<string,object>;object raw;if(root!=null&&root.TryGetValue("inventory_info",out raw))foreach(var item in raw as object[]??new object[0]){var d=item as Dictionary<string,object>;if(d==null)continue;object t,id,q;if(d.TryGetValue("item_master_type",out t)&&d.TryGetValue("item_master_id",out id)&&d.TryGetValue("item_quantity",out q)&&Convert.ToInt32(t)==75&&Convert.ToInt32(id)==2)return Math.Max(0,Convert.ToInt32(q));}}catch{}return 0;}
    public static List<ArtifactRow> Run(string json,string filter,string category="",string mode="",IList<string> liveEvents=null,IEnumerable<string> priorityMonsters=null,IEnumerable<long> reappTargets=null,IEnumerable<long> excludedArtifacts=null){
      string root=AppDomain.CurrentDomain.BaseDirectory,engine=Path.Combine(root,"ArtifactManagerEngine.exe"),data=Path.Combine(root,"Artifact_Manager_Data.json"),temp=Path.Combine(Path.GetTempPath(),"artifact_app_"+Guid.NewGuid().ToString("N")+".tsv"),priorityFile=Path.Combine(Path.GetTempPath(),"artifact_priority_"+Guid.NewGuid().ToString("N")+".txt"),targetFile=Path.Combine(Path.GetTempPath(),"artifact_targets_"+Guid.NewGuid().ToString("N")+".txt"),merged="";if(!File.Exists(engine)||!File.Exists(data))throw new FileNotFoundException("Le moteur ou sa base de données est absent du dossier de l’application.");string input=json;var excluded=new HashSet<long>(excludedArtifacts??Enumerable.Empty<long>());if((liveEvents!=null&&liveEvents.Count>0)||excluded.Count>0){merged=BuildMergedJson(json,liveEvents,excluded);if(merged.Length>0)input=merged;}File.WriteAllLines(priorityFile,priorityMonsters??Enumerable.Empty<string>(),Encoding.UTF8);File.WriteAllLines(targetFile,(reappTargets??Enumerable.Empty<long>()).Select(x=>x.ToString(CultureInfo.InvariantCulture)),Encoding.UTF8);
      var psi=new ProcessStartInfo(engine){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};psi.Arguments=Q(input)+" "+Q(data)+" "+Q(temp)+" "+Q(filter??"")+" "+Q(category??"")+" "+Q(mode??"")+" "+Q(priorityFile)+" "+Q(targetFile)+" "+RetentionLimit.ToString(CultureInfo.InvariantCulture)+" "+(FixedMode?"fixed":"count")+" "+FixedValue.ToString(CultureInfo.InvariantCulture);using(var p=Process.Start(psi)){p.WaitForExit();if(p.ExitCode!=0)throw new Exception("Le moteur d’analyse a renvoyé l’erreur "+p.ExitCode+".");}
      var result=new List<ArtifactRow>();try{foreach(string line in File.ReadAllLines(temp,Encoding.UTF8)){if(string.IsNullOrWhiteSpace(line))continue;var c=line.Split(new[]{'\t'});if(c.Length<19)continue;double potential,reappPriority=0,retentionThreshold=0;long rid;int level;double.TryParse(c[12],NumberStyles.Any,CultureInfo.InvariantCulture,out potential);if(c.Length>19)double.TryParse(c[19],NumberStyles.Any,CultureInfo.InvariantCulture,out reappPriority);if(c.Length>21)double.TryParse(c[21],NumberStyles.Any,CultureInfo.InvariantCulture,out retentionThreshold);long.TryParse(c[18],out rid);int.TryParse(c[5],out level);result.Add(new ArtifactRow{Artefact=c[0],Obtained=c[1],Categorie=c[2],Restriction=c[3],Rarete=c[4],Niveau=level,StatPrincipale=c[6],Stat1=c[7],Stat2=c[8],Stat3=c[9],Stat4=c[10],Action=c[11],Potential=potential,Conversion=c[13],Preset=c[14],Mode=c[15],EquipeSur=c[16],Verrouille=c[17],Rid=rid,ReappPriority=reappPriority,ReappReason=c.Length>20?c[20]:"",RetentionThreshold=retentionThreshold,BestMonster=c.Length>22?c[22]:""});}}finally{try{File.Delete(temp);}catch{}try{File.Delete(priorityFile);}catch{}try{File.Delete(targetFile);}catch{}try{if(merged.Length>0)File.Delete(merged);}catch{}}return result;
    }
    public static List<long> ArtifactIds(string json){var result=new List<long>();try{var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};var found=new Dictionary<string,Dictionary<string,object>>();CollectArtifacts(js.DeserializeObject(json),found);foreach(var key in found.Keys){long id;if(long.TryParse(key,out id)&&id>0)result.Add(id);}}catch{}return result;}
    public static List<long> SoldArtifactIds(string json){var result=new List<long>();try{var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};var root=js.DeserializeObject(json) as Dictionary<string,object>;object command,ids,ret;if(root==null||!root.TryGetValue("command",out command)||!string.Equals(Convert.ToString(command),"SellArtifacts",StringComparison.OrdinalIgnoreCase)||(root.TryGetValue("ret_code",out ret)&&Convert.ToInt32(ret)!=0)||!root.TryGetValue("artifact_ids",out ids))return result;foreach(var raw in ids as object[]??new object[0]){long id;if(long.TryParse(Convert.ToString(raw),out id)&&id>0)result.Add(id);}}catch{}return result;}
    public static ArtifactReappraisalComparison CompareReappraisal(string json,IList<string> liveEvents,string response){
      try{
        var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};var root=js.DeserializeObject(response) as Dictionary<string,object>;object raw;if(root==null||!root.TryGetValue("command",out raw)||!IsReappraisalCommand(Convert.ToString(raw)))return null;if(root.TryGetValue("ret_code",out raw)&&Convert.ToInt32(raw)!=0)return null;
        object beforeRaw,afterRaw;var beforeArtifact=root.TryGetValue("artifact_before",out beforeRaw)?beforeRaw as Dictionary<string,object>:null;var afterArtifact=root.TryGetValue("artifact_after",out afterRaw)?afterRaw as Dictionary<string,object>:null;
        if(beforeArtifact!=null&&afterArtifact!=null){object ridRaw;if(!beforeArtifact.TryGetValue("rid",out ridRaw))return null;long rid;if(!long.TryParse(Convert.ToString(ridRaw),out rid)||rid<=0)return null;var beforeEvents=new List<string>();if(liveEvents!=null)beforeEvents.AddRange(liveEvents);beforeEvents.Add(js.Serialize(new Dictionary<string,object>{{"command","ArtifactReappraisalPreviewBefore"},{"artifact",beforeArtifact}}));var afterEvents=new List<string>();if(liveEvents!=null)afterEvents.AddRange(liveEvents);afterEvents.Add(js.Serialize(new Dictionary<string,object>{{"command","ArtifactReappraisalPreviewAfter"},{"artifact",afterArtifact}}));var before=Run(json,"","","",beforeEvents).FirstOrDefault(x=>x.Rid==rid);var after=Run(json,"","","",afterEvents).FirstOrDefault(x=>x.Rid==rid);return before!=null&&after!=null?new ArtifactReappraisalComparison{Before=before,After=after}:null;}
        var candidates=new Dictionary<string,Dictionary<string,object>>();CollectArtifacts(root,candidates);if(candidates.Count==0)return null;var beforeRows=Run(json,"","","",liveEvents);var ids=new HashSet<long>(candidates.Keys.Select(x=>{long id;return long.TryParse(x,out id)?id:0;}));var previous=beforeRows.FirstOrDefault(x=>ids.Contains(x.Rid));if(previous==null)return null;var events=new List<string>();if(liveEvents!=null)events.AddRange(liveEvents);events.Add(response);var next=Run(json,"","","",events).FirstOrDefault(x=>x.Rid==previous.Rid);return next!=null?new ArtifactReappraisalComparison{Before=previous,After=next}:null;
      }catch{return null;}
    }
    public static bool IsReappraisalCommand(string command){return string.Equals(command,"convertArtifactByCoreFragment",StringComparison.OrdinalIgnoreCase)||(command.IndexOf("Artifact",StringComparison.OrdinalIgnoreCase)>=0&&(command.IndexOf("Revalue",StringComparison.OrdinalIgnoreCase)>=0||command.IndexOf("Reapp",StringComparison.OrdinalIgnoreCase)>=0));}
    static string BuildMergedJson(string json,IList<string> events,HashSet<long> excluded){var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};var game=js.DeserializeObject(File.ReadAllText(json,Encoding.UTF8)) as Dictionary<string,object>;var updates=new Dictionary<string,Dictionary<string,object>>();var unitUpdates=new Dictionary<string,Dictionary<string,object>>();foreach(string line in events??new string[0]){try{var parsed=js.DeserializeObject(line);var root=parsed as Dictionary<string,object>;object command,ids,ret;bool sale=root!=null&&root.TryGetValue("command",out command)&&string.Equals(Convert.ToString(command),"SellArtifacts",StringComparison.OrdinalIgnoreCase)&&(!root.TryGetValue("ret_code",out ret)||Convert.ToInt32(ret)==0);if(sale&&root.TryGetValue("artifact_ids",out ids)){foreach(var id in ids as object[]??new object[0]){long value;if(long.TryParse(Convert.ToString(id),out value))excluded.Add(value);}continue;}CollectArtifacts(parsed,updates);CollectUnits(parsed,unitUpdates);}catch{}}if(updates.Count==0&&unitUpdates.Count==0&&excluded.Count==0)return "";foreach(long id in excluded)updates.Remove(id.ToString());ReplaceArtifacts(game,updates);object raw;var list=new List<object>();if(game.TryGetValue("artifacts",out raw))list.AddRange((raw as object[]??new object[0]).Where(x=>{var d=x as Dictionary<string,object>;object id;long value;return d==null||!d.TryGetValue("rid",out id)||!long.TryParse(Convert.ToString(id),out value)||!excluded.Contains(value);}));var present=new HashSet<string>(list.Select(x=>{var d=x as Dictionary<string,object>;object id;return d!=null&&d.TryGetValue("rid",out id)?Convert.ToString(id):"";}));foreach(var kv in updates)if(!present.Contains(kv.Key))list.Add(kv.Value);game["artifacts"]=list.ToArray();var units=new List<object>();if(game.TryGetValue("unit_list",out raw))units.AddRange(raw as object[]??new object[0]);var unitIndex=new Dictionary<string,int>();for(int i=0;i<units.Count;i++){var d=units[i] as Dictionary<string,object>;object id;if(d!=null&&d.TryGetValue("unit_id",out id))unitIndex[Convert.ToString(id)]=i;}foreach(var kv in unitUpdates){int i;if(unitIndex.TryGetValue(kv.Key,out i))units[i]=kv.Value;else units.Add(kv.Value);}foreach(var item in units){var u=item as Dictionary<string,object>;if(u==null||!u.TryGetValue("artifacts",out raw))continue;u["artifacts"]=(raw as object[]??new object[0]).Where(x=>{var d=x as Dictionary<string,object>;object id;long value;return d==null||!d.TryGetValue("rid",out id)||!long.TryParse(Convert.ToString(id),out value)||!excluded.Contains(value);}).ToArray();}game["unit_list"]=units.ToArray();string path=Path.Combine(Path.GetTempPath(),"artifact_live_"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(path,js.Serialize(game),Encoding.UTF8);return path;}
    static void CollectArtifacts(object value,Dictionary<string,Dictionary<string,object>> found){var d=value as Dictionary<string,object>;if(d!=null){object rid;if(d.TryGetValue("rid",out rid)&&d.ContainsKey("pri_effect")&&d.ContainsKey("sec_effects")&&d.ContainsKey("type")){string id=Convert.ToString(rid);if(id.Length>0&&id!="0")found[id]=d;return;}foreach(var kv in d)CollectArtifacts(kv.Value,found);return;}foreach(var x in value as object[]??new object[0])CollectArtifacts(x,found);}
    static void CollectUnits(object value,Dictionary<string,Dictionary<string,object>> found){var d=value as Dictionary<string,object>;if(d!=null){object uid,mid;if(d.TryGetValue("unit_id",out uid)&&d.TryGetValue("unit_master_id",out mid)&&d.ContainsKey("skills")){string id=Convert.ToString(uid);if(id.Length>0&&id!="0")found[id]=d;return;}foreach(var kv in d)CollectUnits(kv.Value,found);return;}foreach(var x in value as object[]??new object[0])CollectUnits(x,found);}
    static void ReplaceArtifacts(object value,Dictionary<string,Dictionary<string,object>> updates){var d=value as Dictionary<string,object>;if(d!=null){foreach(var key in d.Keys.ToList()){var child=d[key] as Dictionary<string,object>;object rid;if(child!=null&&child.TryGetValue("rid",out rid)&&updates.ContainsKey(Convert.ToString(rid)))d[key]=updates[Convert.ToString(rid)];else ReplaceArtifacts(d[key],updates);}return;}var a=value as object[];if(a==null)return;for(int i=0;i<a.Length;i++){var child=a[i] as Dictionary<string,object>;object rid;if(child!=null&&child.TryGetValue("rid",out rid)&&updates.ContainsKey(Convert.ToString(rid)))a[i]=updates[Convert.ToString(rid)];else ReplaceArtifacts(a[i],updates);}}
    static string Q(string s){return "\""+s.Replace("\"","\\\"")+"\"";}
  }
