eptButton=ok;f.CancelButton=cancel;refreshEnabled();update();if(f.ShowDialog(this)!=DialogResult.OK)return;retentionLimit=(int)number.Value;fixedSellThreshold=fixedBox.Checked;fixedSellThresholdValue=(double)fixedNumber.Value;EngineBridge.RetentionLimit=retentionLimit;EngineBridge.FixedMode=fixedSellThreshold;EngineBridge.FixedValue=fixedSellThresholdValue;SaveRetentionLimit();SaveSellThresholdSettings();ImportCurrent(true);RefreshRetentionButton();status.Text=fixedSellThreshold?"Seuil fixe réglé sur "+fixedSellThresholdValue.ToString("0.000"):"Seuil dynamique réglé sur "+retentionLimit.ToString("N0")+" artefacts • seuil actuel : "+(all.Count==0?0:all.Max(x=>x.RetentionThreshold)).ToString("0.000");}
