    void LoadArtifactIcons(){string dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","artifacts");foreach(var name in new[]{"attack","defense","hp","support","water","fire","wind","light","dark"}){string path=Path.Combine(dir,name+".png");if(File.Exists(path)){using(var source=Image.FromFile(path))artifactIcons[name]=new Bitmap(source);}}}
    Image LoadUiImage(string name,int width,int height){try{string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets",name);if(File.Exists(path)){using(var source=Image.FromFile(path))return new Bitmap(source,new Size(width,height));}}catch{}return null;}
    // Meme technique que les pierres de reeval dans l'appli Rune Manager (IconBadge +
    // HighQualityScale) : rendu anti-alias/bicubique au lieu du redimensionnement brut de
    // LoadUiImage (flou/pixelise). Utilise pour l'icone du bouton REAPPRAISAL.
    static Bitmap HighQualityScale(Image source,int width,int height){var result=new Bitmap(width,height);using(var g=Graphics.FromImage(result)){g.SmoothingMode=SmoothingMode.AntiAlias;g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.HighQuality;g.CompositingQuality=CompositingQuality.HighQuality;g.DrawImage(source,new Rectangle(0,0,width,height));}return result;}
    Image LoadUiImageHQ(string name,int width,int height){try{string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets",name);if(File.Exists(path)){using(var source=Image.FromFile(path))return HighQualityScale(source,width,height);}}catch{}return null;}
