    // construction. On recale priorityButton a chaque changement de texte de reappButton.
    void RefreshCoreBadge(){if(reappButton==null)return;reappButton.Text="x"+coreFragments.ToString("N0")+"   REAPPRAISAL";if(priorityButton!=null)priorityButton.Left=reappButton.Right+8;}
    string ArtifactIconKey(ArtifactRow r){if(r.Categorie=="Element"){switch(r.Restriction){case "Eau":return "water";case "Feu":return "fire";case "Vent":return "wind";case "Lumiere":return "light";case "Tenebres":return "dark";}}else{switch(r.Restriction){case "Attaque":return "attack";case "Defense":return "defense";case "PV":return "hp";case "Support":return "support";}}return "attack";}
    void PaintArtifactIcon(object sender,DataGridViewCellPaintingEventArgs e){if(e.RowIndex<0||e.ColumnIndex!=0)return;var r=grid.Rows[e.RowIndex].DataBoundItem as ArtifactRow;if(r==null)return;e.PaintBackground(e.CellBounds,true);Image icon;artifactIcons.TryGetValue(ArtifactIconKey(r),out icon);if(icon!=null){Color grade=r.Rarete=="Legendaire"?Color.FromArgb(255,153,0):Color.FromArgb(170,68,221);int frame=Math.Min(32,e.CellBounds.Height-10),x=e.CellBounds.X+(e.CellBounds.Width-frame)/2,y=e.CellBounds.Y+(e.CellBounds.Height-frame)/2;var rect=new Rectangle(x,y,frame,frame);using(var fill=new SolidBrush(Color.FromArgb(25,grade)))e.Graphics.FillRectangle(fill,rect);using(var pen=new Pen(grade,2))e.Graphics.DrawRectangle(pen,rect);int size=Math.Min(24,frame-6),ix=x+(frame-size)/2,iy=y+(frame-size)/2;e.Graphics.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;e.Graphics.DrawImage(icon,new Rectangle(ix,iy,size,size));string level="+"+r.Niveau;using(var font=new Font("Segoe UI Semibold",7,FontStyle.Bold)){SizeF m=e.Graphics.MeasureString(level,font);int bw=(int)Math.Ceiling(m.Width)+4,bh=13;var badge=new Rectangle(rect.Right-bw+3,rect.Bottom-bh+4,bw,bh);using(var b=new SolidBrush(Color.FromArgb(245,5,14,24)))e.Graphics.FillRectangle(b,badge);using(var p=new Pen(Color.FromArgb(100,120,138)))e.Graphics.DrawRectangle(p,badge);TextRenderer.DrawText(e.Graphics,level,font,badge,Color.White,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);}if(!string.IsNullOrEmpty(r.EquipeSur)){string mp;if(monsterIconByName.TryGetValue(r.EquipeSur,out mp)){var mImg=MonsterImage(mp);if(mImg!=null){int mLeft=e.CellBounds.Left+2,mTop=e.CellBounds.Top+2,mSize=Math.Max(16,Math.Min(rect.Left-mLeft-1,rect.Top-mTop-1));var mBadge=new Rectangle(mLeft,mTop,mSize,mSize);using(var mb=new SolidBrush(Color.FromArgb(245,5,14,24)))e.Graphics.FillRectangle(mb,mBadge);using(var mpen=new Pen(Color.FromArgb(120,200,255)))e.Graphics.DrawRectangle(mpen,mBadge);e.Graphics.DrawImage(mImg,new Rectangle(mBadge.X+1,mBadge.Y+1,mSize-2,mSize-2));}}}grid.Rows[e.RowIndex].Cells[0].ToolTipText=r.Artefact+(string.IsNullOrEmpty(r.EquipeSur)?"":" — équipé sur "+r.EquipeSur);}e.Paint(e.ClipBounds,DataGridViewPaintParts.Border);e.Handled=true;}
    void ChooseJson(){using(var f=new OpenFileDialog{Filter="JSON SWEX (*.json)|*.json",Title="Choisir le fichier JSON SWEX"})if(f.ShowDialog(this)==DialogResult.OK){currentJson=f.FileName;SaveLastJson();ImportCurrent();StartJsonWatcher();}}
    void ImportCurrent(bool automatic=false){
      if(importing)return;if(currentJson.Length==0||!File.Exists(currentJson)){if(!automatic)ChooseJson();return;}
      long topId=automatic?VisibleTopArtifactId():0;int topIndex=automatic?grid.FirstDisplayedScrollingRowIndex:-1;
      try{importing=true;if(!automatic){liveEvents.Clear();liveCoreKnown=false;}UseWaitCursor=true;status.Text=automatic?"Mise à jour automatique en cours…":"Analyse SWLens en cours…";Application.DoEvents();all=EngineBridge.Run(currentJson,"","","",liveEvents,priorityMonsters,reappTargets,soldArtifactIds);var validTargets=new HashSet<long>(all.Where(x=>x.Action=="Cible Reappraisal").Select(x=>x.Rid));if(reappTargets.RemoveWhere(x=>!validTargets.Contains(x))>0)SaveReappSettings();if(!liveCoreKnown)coreFragments=EngineBridge.ReadCoreFragments(currentJson);RefreshCoreBadge();FillFilters();RefreshGrid();if(automatic)RestoreGridPosition(topId,topIndex);status.Text=(automatic?"Mise à jour automatique : ":"Import terminé : ")+Path.GetFileName(currentJson)+" • "+coreFragments.ToString("N0")+" Core Fragments";}catch(Exception ex){if(!automatic)MessageBox.Show(ex.Message,"Artifact Manager",MessageBoxButtons.OK,MessageBoxIcon.Error);else status.Text="Mise à jour automatique reportée : "+ex.Message;}finally{UseWaitCursor=false;importing=false;}
    }
    long VisibleTopArtifactId(){int i=grid.FirstDisplayedScrollingRowIndex;if(i<0||i>=grid.Rows.Count)return 0;var row=grid.Rows[i].DataBoundItem as ArtifactRow;return row==null?0:row.Rid;}
    void RestoreGridPosition(long id,int fallback){if(grid.Rows.Count==0)return;int target=-1;if(id>0)for(int i=0;i<grid.Rows.Count;i++){var row=grid.Rows[i].DataBoundItem as ArtifactRow;if(row!=null&&row.Rid==id){target=i;break;}}if(target<0)target=Math.Min(Math.Max(0,fallback),grid.Rows.Count-1);try{grid.FirstDisplayedScrollingRowIndex=target;}catch{}}
    void MonsterView(string cat,string mode){if(currentJson.Length==0||!File.Exists(currentJson)){ChooseJson();return;}string m=Convert.ToString(monster.Text).Trim();if(m.Length==0){MessageBox.Show("Choisis d’abord un monstre.","Artifact Manager");return;}try{UseWaitCursor=true;all=EngineBridge.Run(currentJson,m,cat,mode,liveEvents,priorityMonsters,reappTargets,soldArtifactIds);obtainedSort=false;viewMode="monstre";FillFilters();RefreshGrid();status.Text="Classement "+m+" — "+cat+" — "+mode;}catch(Exception ex){MessageBox.Show(ex.Message,"Artifact Manager",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{UseWaitCursor=false;}}
    void ShowFullList(bool byObtained){if(currentJson.Length==0||!File.Exists(currentJson)){obtainedSort=byObtained;viewMode=byObtained?"obtained":"potential";RefreshGrid();return;}try{UseWaitCursor=true;all=EngineBridge.Run(currentJson,"","","",liveEvents,priorityMonsters,reappTargets,soldArtifactIds);obtainedSort=byObtained;viewMode=byObtained?"obtained":"potential";FillFilters();RefreshGrid();status.Text=byObtained?"Tri par date d’obtention — tous les artefacts":"Tri par Potential Value — tous les artefacts";}catch(Exception ex){MessageBox.Show(ex.Message,"Artifact Manager",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{UseWaitCursor=false;}}
    void ShowGlobalReappraisal(){if(currentJson.Length==0||!File.Exists(currentJson)){ChooseJson();return;}if(priorityMonsters.Count==0){ShowPriorityMonsters();if(priorityMonsters.Count==0)return;}try{UseWaitCursor=true;status.Text="Analyse des artefacts compatibles avec les monstres Reappraisal prioritaires…";Application.DoEvents();all=EngineBridge.Run(currentJson,"","","",liveEvents,priorityMonsters,reappTargets,soldArtifactIds);obtainedSort=false;viewMode="reappraisal";FillFilters();RefreshGrid();double top10=TopTenThreshold();status.Text="Reappraisal — "+priorityMonsters.Count+" monstre(s) prioritaire(s) • artefacts du top 10 % exclus • coût : 10 fragments";}catch(Exception ex){MessageBox.Show(ex.Message,"Artifact Manager",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{UseWaitCursor=false;}}
    double TopTenThreshold(){if(all.Count==0)return 0;var scores=all.Select(x=>x.Potential).OrderByDescending(x=>x).ToList();int count=Math.Max(1,(int)Math.Ceiling(scores.Count*.10));return scores[Math.Min(scores.Count-1,count-1)];}
    string SettingsDir{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ArtifactManagerModern");}}
    string PriorityPath{get{return Path.Combine(SettingsDir,"reapp_priority_monsters.txt");}}string TargetPath{get{return Path.Combine(SettingsDir,"reapp_targets.txt");}}string SoldPath{get{return Path.Combine(SettingsDir,"sold_artifacts.txt");}}string PriorityMigrationPath{get{return Path.Combine(SettingsDir,"priority_targets_v2.done");}}
    void LoadReappSettings(){try{Directory.CreateDirectory(SettingsDir);if(File.Exists(PriorityPath))foreach(var x in File.ReadAllLines(PriorityPath,Encoding.UTF8))if(x.Trim().Length>0)priorityMonsters.Add(x.Trim());if(File.Exists(TargetPath))foreach(var x in File.ReadAllLines(TargetPath,Encoding.UTF8)){long id;if(long.TryParse(x,out id)&&id>0)reappTargets.Add(id);}if(File.Exists(SoldPath))foreach(var x in File.ReadAllLines(SoldPath,Encoding.UTF8)){long id;if(long.TryParse(x,out id)&&id>0)soldArtifactIds.Add(id);}}catch{}}
    void SaveReappSettings(){try{Directory.CreateDirectory(SettingsDir);File.WriteAllLines(PriorityPath,priorityMonsters.OrderBy(x=>x).ToArray(),Encoding.UTF8);File.WriteAllLines(TargetPath,reappTargets.OrderBy(x=>x).Select(x=>x.ToString()).ToArray(),Encoding.UTF8);File.WriteAllLines(SoldPath,soldArtifactIds.OrderBy(x=>x).Select(x=>x.ToString()).ToArray(),Encoding.UTF8);if(priorityButton!=null)priorityButton.Text="MONSTRES REAPP : "+priorityMonsters.Count;}catch{}}
    void ShowPriorityMonsters(){LoadMonsters();var selected=new HashSet<string>(priorityMonsters,StringComparer.OrdinalIgnoreCase);var f=new Form{Text="Monstres prioritaires — Reappraisal",Size=new Size(760,680),StartPosition=FormStartPosition.CenterParent,BackColor=Bg,ForeColor=Color.White,Font=Font};var title=new Label{Text="Choisis les monstres dont les artefacts doivent être prioritaires",Dock=DockStyle.Top,Height=45,TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI Semibold",12)};var find=new TextBox{Dock=DockStyle.Top,Height=32,BackColor=Panel,ForeColor=Color.White,BorderStyle=BorderStyle.FixedSingle};var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(8),BackColor=Bg};var bottom=new Panel{Dock=DockStyle.Bottom,Height=55,BackColor=Panel};var count=new Label{Location=new Point(12,12),Size=new Size(360,32),ForeColor=Color.FromArgb(116,235,184),TextAlign=ContentAlignment.MiddleLeft};var save=Btn("VALIDER",600,10,130,Color.FromArgb(99,55,160));bottom.Controls.Add(count);bottom.Controls.Add(save);Action rebuild=null;rebuild=()=>{flow.SuspendLayout();flow.Controls.Clear();string q=find.Text.Trim();IEnumerable<MonsterOption> shown=q.Length==0?monsterOptions.OrderByDescending(x=>selected.Contains(x.Name)).ThenBy(x=>x.Name).Take(160):monsterOptions.Where(x=>x.Name.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0||x.Family.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0).OrderByDescending(x=>selected.Contains(x.Name)).ThenBy(x=>x.Name).Take(200);foreach(var o in shown){var b=new Button{Text=o.Name+"\r\n"+o.Family,Tag=o,Size=new Size(224,64),TextAlign=ContentAlignment.MiddleLeft,ImageAlign=ContentAlignment.MiddleLeft,TextImageRelation=TextImageRelation.ImageBeforeText,Padding=new Padding(5),ForeColor=Color.White,BackColor=selected.Contains(o.Name)?Color.FromArgb(99,55,160):Panel,FlatStyle=FlatStyle.Flat};var img=MonsterImage(o.ImagePath);if(img!=null)b.Image=new Bitmap(img,new Size(46,46));b.Click+=(s,e)=>{if(selected.Contains(o.Name))selected.Remove(o.Name);else selected.Add(o.Name);rebuild();};flow.Controls.Add(b);}count.Text=selected.Count+" monstre(s) prioritaire(s)";flow.ResumeLayout();};find.TextChanged+=(s,e)=>rebuild();save.Click+=(s,e)=>{priorityMonsters.Clear();foreach(var x in selected)priorityMonsters.Add(x);SaveReappSettings();f.DialogResult=DialogResult.OK;f.Close();};f.Controls.Add(flow);f.Controls.Add(find);f.Controls.Add(title);f.Controls.Add(bottom);rebuild();if(f.ShowDialog(this)==DialogResult.OK&&currentJson.Length>0){RebuildPriorityTargets();ImportCurrent(true);status.Text=reappTargets.Count+" artefact(s) sous le seuil classé(s) Cible Reappraisal pour les monstres prioritaires";}}
    static string TargetMonsterFromReason(string reason){if(string.IsNullOrEmpty(reason))return "";int bar=reason.IndexOf('|');if(bar<0)return "";string tail=reason.Substring(bar+1).Trim();int dash=tail.IndexOf('—');return (dash<0?tail:tail.Substring(0,dash)).Trim();}
    void RebuildPriorityTargets(){if(currentJson.Length==0||!File.Exists(currentJson)||priorityMonsters.Count==0){reappTargets.Clear();SaveReappSettings();return;}try{UseWaitCursor=true;var baseline=EngineBridge.Run(currentJson,"","","",liveEvents,priorityMonsters,Enumerable.Empty<long>(),soldArtifactIds);double threshold=baseline.Count==0?0:baseline.Max(x=>x.RetentionThreshold);var scores=baseline.Select(x=>x.Potential).OrderByDescending(x=>x).ToList();double top10=scores.Count==0?0:scores[Math.Min(scores.Count-1,Math.Max(1,(int)Math.Ceiling(scores.Count*.10))-1)];reappTargets.Clear();var eligible=baseline.Where(x=>x.Niveau>=15&&x.Rarete=="Legendaire").ToList();foreach(var x in eligible.Where(x=>x.ReappPriority>=top10&&x.Potential<threshold))reappTargets.Add(x.Rid);
      // Monstres prioritaires sans aucun artefact atteignant le top 10 % : seuil relâché pour eux, sinon ils ne reçoivent jamais de cible.
      var coveredMonsters=new HashSet<string>(eligible.Where(x=>x.ReappPriority>=top10).Select(x=>TargetMonsterFromReason(x.ReappReason)).Where(m=>m.Length>0),StringComparer.OrdinalIgnoreCase);
      var starved=new HashSet<string>(priorityMonsters.Where(m=>!coveredMonsters.Contains(m)),StringComparer.OrdinalIgnoreCase);
      if(starved.Count>0)foreach(var x in eligible.Where(x=>x.Potential<threshold&&starved.Contains(TargetMonsterFromReason(x.ReappReason))))reappTargets.Add(x.Rid);
      SaveReappSettings();}finally{UseWaitCursor=false;}}
    void FillFilters(){SetItems(category,"Toutes catégories",all.Select(x=>x.Categorie));SetItems(restriction,"Toutes restrictions",all.Select(x=>x.Restriction));SetItems(action,"Toutes actions",all.Select(x=>x.Action));SetItems(preset,"Tous les presets",all.Select(x=>x.Preset));LoadMonsters();}
    void SetItems(ComboBox c,string first,IEnumerable<string> values){string old=Convert.ToString(c.SelectedItem);c.BeginUpdate();c.Items.Clear();c.Items.Add(first);foreach(var x in values.Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct().OrderBy(x=>x))c.Items.Add(x);c.SelectedItem=c.Items.Contains(old)?old:first;c.EndUpdate();}
    void LoadMonsters(){if(monsterOptions.Count>0)return;try{var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue};var root=(Dictionary<string,object>)js.DeserializeObject(File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Artifact_Manager_Data.json")));string dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","monsters"),catalogPath=Path.Combine(dir,"catalog.json");var catalogById=new Dictionary<int,Dictionary<string,object>>();if(File.Exists(catalogPath))foreach(var raw in js.DeserializeObject(File.ReadAllText(catalogPath,Encoding.UTF8)) as object[]??new object[0]){var d=raw as Dictionary<string,object>;if(d!=null&&d.ContainsKey("id"))catalogById[Convert.ToInt32(d["id"])]=d;}var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);object profilesRaw;if(root.TryGetValue("profiles",out profilesRaw))foreach(var raw in profilesRaw as object[]??new object[0]){var p=raw as Dictionary<string,object>;if(p==null||!p.ContainsKey("monster"))continue;string name=Convert.ToString(p["monster"]);int id=p.ContainsKey("monster_id")?Convert.ToInt32(p["monster_id"]):0;string unique=id+"|"+name;if(name.Length==0||!seen.Add(unique))continue;Dictionary<string,object> c;catalogById.TryGetValue(id,out c);string imgPath=id>0?Path.Combine(dir,id+".png"):"";monsterOptions.Add(new MonsterOption{Id=id,Name=name,Family=c!=null&&c.ContainsKey("family")?Convert.ToString(c["family"]):"",Element=c!=null&&c.ContainsKey("element")?Convert.ToString(c["element"]):p.ContainsKey("element")?Convert.ToString(p["element"]):"",ImagePath=imgPath});if(imgPath.Length>0&&!monsterIconByName.ContainsKey(name))monsterIconByName[name]=imgPath;}monsterOptions.Sort((a,b)=>{int n=string.Compare(a.Name,b.Name,StringComparison.OrdinalIgnoreCase);return n!=0?n:string.Compare(a.Element,b.Element,StringComparison.OrdinalIgnoreCase);});monster.Items.AddRange(monsterOptions.Cast<object>().ToArray());}catch(Exception ex){status.Text="Catalogue SWLens indisponible : "+ex.Message;}}
    void FilterMonsterChoices(){if(filteringMonsters||monsterOptions.Count==0)return;string typed=monster.Text;int caret=monster.SelectionStart;var matches=monsterOptions.Where(x=>x.Name.IndexOf(typed,StringComparison.OrdinalIgnoreCase)>=0||x.Family.IndexOf(typed,StringComparison.OrdinalIgnoreCase)>=0).Take(80).Cast<object>().ToArray();try{filteringMonsters=true;monster.BeginUpdate();monster.Items.Clear();monster.Items.AddRange(matches);monster.Text=typed;monster.SelectionStart=Math.Min(caret,typed.Length);monster.SelectionLength=0;monster.DroppedDown=typed.Length>0&&matches.Length>0;}finally{monster.EndUpdate();filteringMonsters=false;}}
    Image MonsterImage(string path){if(string.IsNullOrWhiteSpace(path)||!File.Exists(path))return null;Image image;if(monsterImages.TryGetValue(path,out image))return image;try{using(var source=Image.FromFile(path))image=new Bitmap(source);monsterImages[path]=image;return image;}catch{return null;}}
    void DrawMonsterItem(object sender,DrawItemEventArgs e){e.DrawBackground();if(e.Index<0){e.DrawFocusRectangle();return;}var option=monster.Items[e.Index] as MonsterOption;if(option==null){TextRenderer.DrawText(e.Graphics,Convert.ToString(monster.Items[e.Index]),Font,e.Bounds,Color.White,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);return;}bool selected=(e.State&DrawItemState.Selected)!=0;Color back=selected?Color.FromArgb(45,54,57):Bg;using(var b=new SolidBrush(back))e.Graphics.FillRectangle(b,e.Bounds);var icon=MonsterImage(option.ImagePath);int size=Math.Min(40,e.Bounds.Height-6),x=e.Bounds.X+5,y=e.Bounds.Y+(e.Bounds.Height-size)/2;if(icon!=null)e.Graphics.DrawImage(icon,new Rectangle(x,y,size,size));using(var nameFont=new Font("Segoe UI Semibold",10)){TextRenderer.DrawText(e.Graphics,option.Name,nameFont,new Rectangle(x+size+8,e.Bounds.Y+4,e.Bounds.Width-size-72,21),Color.White,TextFormatFlags.Left|TextFormatFlags.EndEllipsis);}using(var familyFont=new Font("Segoe UI",8)){TextRenderer.DrawText(e.Graphics,option.Family,familyFont,new Rectangle(x+size+8,e.Bounds.Y+24,e.Bounds.Width-size-72,18),Color.FromArgb(175,175,175),TextFormatFlags.Left|TextFormatFlags.EndEllipsis);}Color ec=option.Element=="fire"?Color.FromArgb(235,75,65):option.Element=="water"?Color.FromArgb(45,145,235):option.Element=="wind"?Color.FromArgb(225,185,45):option.Element=="light"?Color.FromArgb(225,215,170):Color.FromArgb(150,90,190);using(var b=new SolidBrush(ec))e.Graphics.FillEllipse(b,e.Bounds.Right-24,e.Bounds.Y+(e.Bounds.Height-14)/2,14,14);e.DrawFocusRectangle();}
    void RefreshGrid(){IEnumerable<ArtifactRow> q=all;string text=search.Text.Trim();if(text.Length>0)q=q.Where(x=>(x.Artefact+" "+x.StatPrincipale+" "+x.Stat1+" "+x.Stat2+" "+x.Stat3+" "+x.Stat4+" "+x.Preset+" "+x.EquipeSur).IndexOf(text,StringComparison.OrdinalIgnoreCase)>=0);if(category.SelectedIndex>0)q=q.Where(x=>x.Categorie==Convert.ToString(category.SelectedItem));if(restriction.SelectedIndex>0)q=q.Where(x=>x.Restriction==Convert.ToString(restriction.SelectedItem));if(action.SelectedIndex>0)q=q.Where(x=>x.Action==Convert.ToString(action.SelectedItem));if(preset.SelectedIndex>0)q=q.Where(x=>x.Preset==Convert.ToString(preset.SelectedItem));bool reapp=viewMode=="reappraisal";grid.Columns[9].DataPropertyName="Potential";grid.Columns[9].HeaderText=reapp?"Score actuel":"Potential Value";grid.Columns[10].DataPropertyName=reapp?"ReappPriority":"Conversion";grid.Columns[10].HeaderText=reapp?"Maximum avec 4 rolls":"Conversion conseillée";grid.Columns[11].DataPropertyName=reapp?"ReappGain":"Preset";grid.Columns[11].HeaderText=reapp?"Gain potentiel":"Meilleur preset";double top10=TopTenThreshold();if(reapp)q=q.Where(x=>x.Niveau>=15&&x.Rarete=="Legendaire"&&(x.Action=="Cible Reappraisal"||(x.Action=="Keep"&&x.ReappPriority>=top10&&x.Potential<top10))).OrderByDescending(x=>x.Action=="Cible Reappraisal").ThenByDescending(x=>x.ReappGain).ThenByDescending(x=>x.ReappPriority).ThenBy(x=>x.Potential).ThenByDescending(x=>x.Rid);else q=obtainedSort?q.OrderByDescending(x=>x.ObtainedDate).ThenByDescending(x=>x.Rid):q.OrderByDescending(x=>x.Potential);var list=q.ToList();grid.DataSource=new BindingList<ArtifactRow>(list);var keptAll=all.Where(x=>x.Action=="Keep").ToList();int targetCount=all.Count(x=>x.Action=="Cible Reappraisal");int sellCount=all.Count(x=>x.Action=="Sell");double threshold=all.Count==0?0:all.Max(x=>x.RetentionThreshold);summary.Text="TOTAL  "+all.Count.ToString("N0")+"     KEEP  "+keptAll.Count.ToString("N0")+"     SELL  "+sellCount.ToString("N0")+"     CIBLE REAPPRAISAL  "+targetCount.ToString("N0")+"     AFFICHÉES  "+list.Count.ToString("N0")+"     seuil "+threshold.ToString("0.000")+" pour "+keptAll.Count.ToString("N0")+"/"+retentionLimit.ToString("N0")+(reapp?" • top 10 % ≥ "+top10.ToString("0.000")+" exclus • "+priorityMonsters.Count+" monstre(s) prioritaire(s) • "+coreFragments.ToString("N0")+" fragments":"");}
    void StartRealtime(){StartJsonWatcher();StartLiveLog();}
    void StartJsonWatcher(){if(string.IsNullOrWhiteSpace(currentJson)||!File.Exists(currentJson))return;try{if(jsonWatcher!=null)jsonWatcher.Dispose();jsonWatcher=new FileSystemWatcher(Path.GetDirectoryName(currentJson),Path.GetFileName(currentJson));jsonWatcher.NotifyFilter=NotifyFilters.LastWrite|NotifyFilters.Size|NotifyFilters.FileName;jsonWatcher.Changed+=(s,e)=>QueueJson(e.FullPath);jsonWatcher.Created+=(s,e)=>QueueJson(e.FullPath);jsonWatcher.Renamed+=(s,e)=>QueueJson(e.FullPath);jsonWatcher.EnableRaisingEvents=true;status.Text=(status.Text.Length>0?status.Text+" • ":"")+"Surveillance JSON active";}catch(Exception ex){status.Text="Surveillance JSON indisponible : "+ex.Message;}}
    void QueueJson(string path){if(IsDisposed)return;BeginInvoke((Action)(()=>{pendingJson=path;jsonDebounce.Stop();jsonDebounce.Start();}));}
    void StartLiveLog(){liveLogPath=@"C:\Users\Great-Lucky\Desktop\Summoners War Exporter Files\full_log.txt";try{int recovered=0;if(soldArtifactIds.Count==0&&File.Exists(liveLogPath)){foreach(string line in File.ReadLines(liveLogPath,Encoding.UTF8)){if(line.IndexOf("\"command\":\"SellArtifacts\"",StringComparison.OrdinalIgnoreCase)<0||line.IndexOf("\"ret_code\":0",StringComparison.OrdinalIgnoreCase)<0)continue;foreach(long id in EngineBridge.SoldArtifactIds(line))if(soldArtifactIds.Add(id))recovered++;}if(recovered>0){SaveReappSettings();ImportCurrent(true);}}liveLogOffset=File.Exists(liveLogPath)?new FileInfo(liveLogPath).Length:0;liveLogPending="";liveAwaitingResponse=false;liveLogTimer.Start();status.Text=(status.Text.Length>0?status.Text+" • ":"")+"Mise à jour SWEX active"+(recovered>0?" • "+recovered+" vente(s) historique(s) restaurée(s)":"");}catch(Exception ex){status.Text="Surveillance SWEX indisponible : "+ex.Message;}}
    void ReadLiveLog(){if(string.IsNullOrWhiteSpace(liveLogPath)||!File.Exists(liveLogPath))return;try{using(var fs=new FileStream(liveLogPath,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(fs.Length<liveLogOffset){liveLogOffset=0;liveLogPending="";liveAwaitingResponse=false;}if(fs.Length==liveLogOffset)return;fs.Seek(liveLogOffset,SeekOrigin.Begin);using(var sr=new StreamReader(fs,Encoding.UTF8,true,4096,true)){liveLogPending+=sr.ReadToEnd();liveLogOffset=fs.Position;}}ProcessLiveLog();}catch(IOException){}catch(UnauthorizedAccessException){}catch(Exception ex){status.Text="Lecture SWEX interrompue : "+ex.Message;}}
    void ProcessLiveLog(){string normalized=liveLogPending.Replace("\r\n","\n");int last=normalized.LastIndexOf('\n');if(last<0)return;string complete=normalized.Substring(0,last+1);liveLogPending=normalized.Substring(last+1);bool artifactChanged=false,rosterChanged=false,coreChanged=false,settingsChanged=false;foreach(string raw in complete.Split(new[]{'\n'})){string line=raw.Trim();if(line=="Response:"){liveAwaitingResponse=true;continue;}if(line=="Request:"){liveAwaitingResponse=false;continue;}if(!liveAwaitingResponse||line.Length==0)continue;liveAwaitingResponse=false;int found;if(TryReadLiveCoreFragments(line,out found)&&found!=coreFragments){coreFragments=found;liveCoreKnown=true;coreChanged=true;}var sold=EngineBridge.SoldArtifactIds(line);if(sold.Count>0){foreach(long id in sold){if(soldArtifactIds.Add(id))settingsChanged=true;if(reappTargets.Remove(id))settingsChanged=true;}liveEvents.Add(line);if(liveEvents.Count>300)liveEvents.RemoveAt(0);artifactChanged=true;continue;}var ids=EngineBridge.ArtifactIds(line);var comparison=EngineBridge.CompareReappraisal(currentJson,liveEvents,line);if(comparison!=null){foreach(long id in ids)if(reappTargets.Remove(id))settingsChanged=true;ShowReappraisalDecision(comparison);artifactChanged=true;continue;}if(IsMutableArtifactEvent(line)||IsMonsterRosterEvent(line)){liveEvents.Add(line);if(liveEvents.Count>300)liveEvents.RemoveAt(0);if(IsMonsterRosterEvent(line))rosterChanged=true;else{artifactChanged=true;if(!IsArtifactReappraisalEvent(line))foreach(long id in ids)if(reappTargets.Add(id))settingsChanged=true;}}}if(settingsChanged)SaveReappSettings();if(artifactChanged||rosterChanged){ImportCurrent(true);if(rosterChanged)status.Text="Nouveau monstre détecté : scores et seuil des 1 500 artefacts recalculés en temps réel";else status.Text=soldArtifactIds.Count+" artefact(s) vendu(s) conservé(s) hors de la liste • ordre Obtained recalculé";}else if(coreChanged){RefreshCoreBadge();RefreshGrid();status.Text="Core Fragments synchronisés en temps réel : "+coreFragments.ToString("N0");}}
    void ShowReappraisalDecision(ArtifactReappraisalComparison c){var f=new Form{Text="Choix de Reappraisal",Size=new Size(670,390),StartPosition=FormStartPosition.Manual,TopMost=true,BackColor=Bg,ForeColor=Color.White,FormBorderStyle=FormBorderStyle.FixedToolWindow,ShowInTaskbar=false};var area=Screen.PrimaryScreen.WorkingArea;f.Location=new Point(area.Right-f.Width-20,area.Top+20);string verdict=c.TakeAfter?"PRENDRE LE NOUVEL ARTEFACT":"GARDER L’ARTEFACT ACTUEL";Color verdictColor=c.TakeAfter?Color.FromArgb(30,235,155):Color.FromArgb(255,190,60);var title=new Label{Text=verdict,ForeColor=verdictColor,Font=new Font("Segoe UI",17,FontStyle.Bold),AutoSize=false,TextAlign=ContentAlignment.MiddleCenter,Dock=DockStyle.Top,Height=58};var beforeLabel=ComparisonPanel("ACTUEL",c.Before,new Point(18,70));var afterLabel=ComparisonPanel("NOUVEAU",c.After,new Point(340,70));var delta=new Label{Text="Écart de Potential : "+(c.After.Potential-c.Before.Potential).ToString("+0.000;-0.000;0.000"),ForeColor=verdictColor,Font=new Font("Segoe UI Semibold",11),AutoSize=false,TextAlign=ContentAlignment.MiddleCenter,Location=new Point(18,310),Size=new Size(626,28)};var close=new Button{Text="FERMER",Location=new Point(524,342),Size=new Size(120,30),BackColor=Color.FromArgb(180,45,65),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};close.Click+=(s,e)=>f.Close();f.Controls.Add(title);f.Controls.Add(beforeLabel);f.Controls.Add(afterLabel);f.Controls.Add(delta);f.Controls.Add(close);f.Show(this);}
    Control ComparisonPanel(string heading,ArtifactRow r,Point location){return new Label{Text=heading+"\r\nPotential  "+r.Potential.ToString("0.000")+"\r\nPreset : "+r.Preset+"\r\n\r\n"+r.StatPrincipale+"\r\n"+r.Stat1+"\r\n"+r.Stat2+"\r\n"+r.Stat3+"\r\n"+r.Stat4,Font=new Font("Segoe UI",10),AutoSize=false,Location=location,Size=new Size(304,232),Padding=new Padding(10),BackColor=Panel};}
    bool IsMutableArtifactEvent(string json){if(json.IndexOf("\"artifact",StringComparison.OrdinalIgnoreCase)<0)return false;try{var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};var root=js.DeserializeObject(json) as Dictionary<string,object>;object c;if(root==null||!root.TryGetValue("command",out c))return false;string command=Convert.ToString(c);return !(command.StartsWith("Get",StringComparison.OrdinalIgnoreCase)||command.StartsWith("Hub",StringComparison.OrdinalIgnoreCase)||command.IndexOf("List",StringComparison.OrdinalIgnoreCase)>=0||command.IndexOf("Info",StringComparison.OrdinalIgnoreCase)>=0);}catch{return false;}}
    bool IsArtifactReappraisalEvent(string json){try{var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};var root=js.DeserializeObject(json) as Dictionary<string,object>;object c;return root!=null&&root.TryGetValue("command",out c)&&EngineBridge.IsReappraisalCommand(Convert.ToString(c));}catch{return false;}}
    bool IsMonsterRosterEvent(string json){if(json.IndexOf("\"unit_master_id\"",StringComparison.OrdinalIgnoreCase)<0)return false;try{var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};var root=js.DeserializeObject(json) as Dictionary<string,object>;object c;if(root==null||!root.TryGetValue("command",out c))return false;string command=Convert.ToString(c);return command.Equals("SummonUnit",StringComparison.OrdinalIgnoreCase)||command.IndexOf("Storage",StringComparison.OrdinalIgnoreCase)>=0;}catch{return false;}}
    bool TryReadLiveCoreFragments(string json,out int amount){amount=-1;try{var js=new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};return FindCoreFragments(js.DeserializeObject(json),ref amount);}catch{return false;}}
    bool FindCoreFragments(object value,ref int amount){var d=value as Dictionary<string,object>;if(d!=null){object t,id,q;if(d.TryGetValue("item_master_type",out t)&&d.TryGetValue("item_master_id",out id)&&Convert.ToInt32(t)==75&&Convert.ToInt32(id)==2&&(d.TryGetValue("item_quantity_curr",out q)||d.TryGetValue("item_quantity",out q))&&(d.ContainsKey("rid")||d.ContainsKey("wizard_id")||d.ContainsKey("item_quantity_curr"))){amount=Math.Max(0,Convert.ToInt32(q));return true;}bool found=false;foreach(var kv in d)if(FindCoreFragments(kv.Value,ref amount))found=true;return found;}bool any=false;foreach(var x in value as object[]??new object[0])if(FindCoreFragments(x,ref amount))any=true;return any;}
    string LastPath{get{return Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"artifact_last_json.txt");}}void SaveLastJson(){try{File.WriteAllText(LastPath,currentJson);}catch{}}void LoadLastJson(){try{if(File.Exists(LastPath)){currentJson=File.ReadAllText(LastPath).Trim();if(File.Exists(currentJson)){if(priorityMonsters.Count>0&&!File.Exists(PriorityMigrationPath)){RebuildPriorityTargets();File.WriteAllText(PriorityMigrationPath,DateTime.Now.ToString("O"));}ImportCurrent();}}}catch{}}
